 plain='I worship the lotus-eyed Lord: dark as a monsoon cloud, His yellow silk flashing like lightning, a wild-flower garland on His chest, His feet rosy red.',
 words=[('vidyut-udyota-vat','<b>like a flash of lightning</b>'),('vāsas','<b>garment</b>'),('prāvṛṭ-ambhoda','<b>rain cloud of the monsoon</b>'),('vanyā mālā','a <b>garland of forest flowers</b>'),('lohita-aṅghri','<b>red feet</b>'),('vārija-akṣa','<b>lotus-eyed</b>')],
